func (h *nativeHistory) verifyProfile(role string, profile WorkloadProfile, p nativeProfileProvenance) error {
	r := h.services
	if r.roots == nil {
		return errors.New("native profile trust roots are unavailable")
	}
	var signed WorkloadProfile
	if len(p.Spec) != 0 {
		if len(p.Manifest)+len(p.Config)+len(p.MaterialChain)+len(p.Identity) != 0 {
			return errors.New("ambiguous native profile provenance")
		}
		verified, err := cellspec.VerifyHistorical(p.Spec, r.roots.current(), r.identity)
		if err != nil {
			return err
		}
		found := false
		for _, s := range verified.Spec.Services {
			if s.Role == role {
				signed, found = s.Profile, true
			}
		}
		if !found {
			return errors.New("signed cell spec does not contain the retained role")
		}
	} else {
		envelope, err := trust.DecodeEnvelope(p.Manifest)
		if err != nil {
			return err
		}
		manifest, err := bootstrap.ManifestPayload(envelope.Payload)
		if err != nil {
			return err
		}
		if manifest.DeploymentID != r.identity.DeploymentID || strings.ToLower(string(manifest.Cell)) != r.identity.Cell || manifest.Environment != r.identity.Environment {
			return errors.New("retained controller manifest belongs to another deployment")
		}
		identity, err := bootstrapstart.DecodeAcceptedIdentity(p.Identity)
		if err != nil {
			return err
		}
		if identity.DeploymentID != manifest.DeploymentID || identity.Cell != string(manifest.Cell) || identity.Slot != manifest.Slot {
			return errors.New("retained accepted identity belongs to another controller")
		}
		acceptance, err := identity.AcceptanceSHA256()
		if err != nil {
			return err
		}
		_, err = bootstrap.VerifyHistoricalManifest(envelope, r.roots.current(), bootstrap.ManifestExpectation{
			DeploymentID: r.identity.DeploymentID, Cell: manifest.Cell, Environment: r.identity.Environment,
			ClusterID: manifest.ClusterID, Slot: manifest.Slot, ImageOCID: manifest.ImageOCID,
			StorageDomain: manifest.StorageDomain, ControllerSlots: manifest.ControllerSlots}, bootstrap.ManifestTrustPolicy())
		if err != nil {
			return err
		}
		want := manifest.ControllerConfigSHA256
		if len(p.MaterialChain) != 0 {
			chain, err := bootstrap.DecodeMaterialGenerationChain(p.MaterialChain)
			if err != nil {
				return err
			}
			verified, err := bootstrap.VerifyAdoptedMaterialGenerationChain(chain, r.roots.current(), bootstrap.MaterialGenerationExpectation{
				DeploymentID: manifest.DeploymentID, Environment: manifest.Environment, ClusterID: manifest.ClusterID,
				Cell: manifest.Cell, ControllerSlots: manifest.ControllerSlots})
			if err != nil {
				return err
			}
			for _, pin := range verified[len(verified)-1].Generation().ControllerConfigs {
				if pin.Slot == manifest.Slot {
					if pin.AcceptanceSHA256 != acceptance {
						return errors.New("retained material/config acceptance mismatch")
					}
					want = pin.SHA256
				}
			}
		}
		cfg, err := ValidateLoadedControllerConfig(manifest, p.Config, want, "")
		if err != nil {
			return err
		}
		signed = cfg.Controller.Workloads[role]
	}
	if nativeProfileDigest(signed) != nativeProfileDigest(profile) {
		return errors.New("retained profile differs from signed provenance")
	}
	current := r.profiles()
	approved, ok := current[role]
	if !ok {
		return errors.New("retained native role is no longer approved")
	}
	if role == terrabase.Role && approved.Env[terrabase.EnvPeers] != profile.Env[terrabase.EnvPeers] {
		return errors.New("retained TerraBase membership differs from current authority")
	}
	current[role] = profile
	return validateWorkloadProfiles(r.cell, current)
}

func ValidateLoadedControllerConfig(manifest bootstrap.Manifest, config []byte, want, observedPrivateIP string,
) (Config, error) {
	manifest.ControllerConfig, manifest.ControllerConfigSHA256 = config, want
	return ValidateInstalledControllerConfig(manifest, observedPrivateIP)
}

// ValidateInstalledControllerConfig checks the role-specific meaning of the
// exact signed bytes. Guest installation and every restart re-check configs
// against the current schema, so the digest covers the bytes, not a
// re-encoding. observedPrivateIP is empty during offline signing and is the
// independently observed primary VNIC address on the guest.
func ValidateInstalledControllerConfig(manifest bootstrap.Manifest, observedPrivateIP string) (Config, error) {
	return validateControllerConfig(controllerConfigBinding{
		DeploymentID: manifest.DeploymentID, Cell: manifest.Cell, Slot: manifest.Slot,
		SeedSlot: manifest.SeedSlot, Environment: manifest.Environment, ControllerSlots: manifest.ControllerSlots,
		ControllerConfig: manifest.ControllerConfig, ControllerConfigSHA256: manifest.ControllerConfigSHA256,
		ControllerFiles: manifest.ControllerFiles, Secrets: manifest.Secrets,
		IntentGeneration: manifest.IntentGeneration, IntentSHA256: manifest.IntentSHA256,
	}, observedPrivateIP)
}

func validateControllerConfig(manifest controllerConfigBinding, observedPrivateIP string) (Config, error) {
	if len(manifest.ControllerConfig) > bootstrap.MaxControllerConfigBytes ||
		controllerSHA256(manifest.ControllerConfig) != manifest.ControllerConfigSHA256 {
		return Config{}, errors.New("signed controller config differs from its signed digest")
	}
	cfg, err := decodeConfig(manifest.ControllerConfig)
	if err != nil {
		return Config{}, fmt.Errorf("decode signed controller config: %w", err)
	}
	hostConfig := cfg.Host
	if len(hostConfig.Roles) == 0 {
		hostConfig.Roles = nil
	}
	if cfg.NATS.Cell != strings.ToLower(string(manifest.Cell)) || cfg.NATS.Instance != manifest.Slot ||
		cfg.NATS.Replicas != len(manifest.ControllerSlots) || cfg.NATS.Embedded == nil ||
		cfg.Controller.CandidateID != entityid.Derive("controller", manifest.DeploymentID, string(manifest.Cell), manifest.Slot) ||
		!reflect.DeepEqual(hostConfig, HostConfig{}) ||
		cfg.Operator != (OperatorConfig{}) ||
		cfg.Controller.OciRegionConfig != controllerSidecarPath("oci-region.json") ||
		cfg.Controller.OciRegionIntentFile != controllerSidecarPath("oci-region-intent.json") ||
		cfg.Controller.PlacementConfig != controllerSidecarPath("placement.json") ||
		cfg.NATS.NKeySeedFile != "" || cfg.Controller.TrustKeyFile != "" || cfg.Controller.SpecTrust != nil {
		return Config{}, errors.New("signed controller config does not match role, slot, or fixed paths")
	}

func (h *nativeHistory) restore(ctx context.Context, request nativePrepareRequest, actor string) (reply nativePrepareReply, restoreErr error) {
	i := request.Intent
	if err := i.Validate(); err != nil {
		return reply, err
	}
	if !slices.Contains(serviceReleaseRoles, i.Role) || i.Cell != h.services.cell || request.RecoveryOf != "" || request.ResumeOf != "" {
		return reply, delivery.ErrInvalid
	}
	defer func() {
		if errors.Is(restoreErr, delivery.ErrInvalid) && ctx.Err() == nil {
			restoreErr = errors.Join(restoreErr, h.deliveries.RefuseIntent(ctx, i, actor, i.AuthorityEpoch, "rollback target is not an eligible, unambiguous retained good release/configuration pair"))
		}
	}()
	h.effects.Lock()
	defer h.effects.Unlock()
	if err := h.fencer.Guard(ctx, i.AuthorityEpoch); err != nil {
		return reply, err
	}
	h.services.launches.RLock()
	defer h.services.launches.RUnlock()
	state, revision, err := h.load(ctx, i.Role)
	if err != nil {
		return reply, err
	}
	fingerprint, err := i.Fingerprint()
	if err != nil {
		return reply, err
	}
	receipt, statusErr := h.deliveries.StatusFor(ctx, i)
	if statusErr != nil && !errors.Is(statusErr, delivery.ErrPending) {
		return reply, statusErr
	}
	if statusErr == nil && (receipt.Status != "accepted" || state.Recovery == nil || state.Recovery.Fingerprint != fingerprint) {
		return reply, delivery.ErrConflict
	}
	if state.Pending != nil && state.Pending.Intent.OperationID == i.OperationID {
		return reply, delivery.ErrConflict
	}
	if state.Recovery != nil && state.Recovery.Fingerprint == fingerprint {
		if err := h.verifyProfile(i.Role, state.Recovery.Profile, state.Recovery.Provenance); err != nil {
			return reply, fmt.Errorf("%w: %w", delivery.ErrInvalid, err)
		}
		if err := h.refuseKnownBad(ctx, state.Recovery.Artifact); err != nil {
			return reply, err
		}
		if bad, err := h.badProfile(ctx, *state.Recovery); err != nil {
			return reply, err
		} else if bad {
			return reply, fmt.Errorf("%w: retained artifact/profile is known bad", delivery.ErrInvalid)
		}
		if !slices.ContainsFunc(state.Good, func(g nativeGoodRelease) bool { return g.Binding.Fingerprint == fingerprint }) &&
			!time.Now().Before(state.Recovery.Deadline) {
			return reply, fmt.Errorf("%w: rollback observation deadline expired: %w", delivery.ErrInvalid, context.DeadlineExceeded)
		}
		return nativePrepareReply{Intent: i}, h.prepareGate(ctx, i, state)
	}
	if state.Recovery != nil && !slices.ContainsFunc(state.Good, func(g nativeGoodRelease) bool {
		return g.Binding.Fingerprint == state.Recovery.Fingerprint
	}) {
		return reply, delivery.ErrConflict
	}
	target, err := nativeRestoreTarget(state, i)
	if err != nil {
		return reply, err
	}
	if err := h.verifyProfile(i.Role, target.Binding.Profile, target.Binding.Provenance); err != nil {
		return reply, fmt.Errorf("%w: %w", delivery.ErrInvalid, err)
	}
	if err := h.refuseKnownBad(ctx, target.Binding.Artifact); err != nil {
		return reply, err
	}
	if bad, err := h.badProfile(ctx, target.Binding); err != nil {
		return reply, err
	} else if bad {
		return reply, fmt.Errorf("%w: retained artifact/profile is known bad", delivery.ErrInvalid)
	}
	desired, err := h.hosts.ListDesired(ctx, i.Role)
	if err != nil {
		return reply, err
	}
	minimum := nextReleaseGeneration(desired)
	for _, binding := range []*nativeReleaseBinding{state.Pending, state.Recovery} {
		if binding != nil {
			if binding.Intent.Generation == ^uint64(0) {
				return reply, fmt.Errorf("%w: rollback generation space exhausted", delivery.ErrInvalid)
			}
			minimum = max(minimum, binding.Intent.Generation+1)
		}
	}
	if minimum == 0 || i.Generation < minimum {
		return reply, fmt.Errorf("%w: rollback generation does not supersede selected and committed releases", delivery.ErrInvalid)
	}
	if _, err := workload.ReleaseGeneration(i.Generation); err != nil {
		return reply, fmt.Errorf("%w: %w", delivery.ErrInvalid, err)
	}
	if request.Deadline.IsZero() || !time.Now().Before(request.Deadline) || request.Deadline.After(time.Now().Add(rollout.ObservationBudget)) {
		return reply, fmt.Errorf("%w: invalid fixed rollback deadline", delivery.ErrInvalid)
	}
	binding, err := nativeBinding(i, target.Binding.Artifact, target.Binding.Profile, target.Binding.Provenance)
	if err != nil {
		return reply, err
	}
	binding.Deadline = request.Deadline.UTC()
	state.Recovery = &binding
	// Manual restoration preserves the good release the user chooses to leave.
	if err := h.save(ctx, i.AuthorityEpoch, i.Role, state, revision); err != nil {
		return reply, err
	}
	if err := h.prepareGate(ctx, i, state); err != nil {
		return reply, err
	}
	return nativePrepareReply{Intent: i}, nil
}

func nativeRestoreMatches(binding nativeReleaseBinding, intent delivery.Intent) bool {
	previous := binding.Intent
	return previous.Cell == intent.Cell && previous.Role == intent.Role && previous.Environment == intent.Environment &&
		previous.Source == intent.Source && previous.ArtifactDigest == intent.ArtifactDigest &&
		previous.ManifestDigest == intent.ManifestDigest && previous.ConfigDigest == intent.ConfigDigest &&
		previous.DesiredReplicas == intent.DesiredReplicas
}

func nativeRestoreTarget(state nativeReleaseHistory, intent delivery.Intent) (*nativeGoodRelease, error) {
	if state.Previous != nil && nativeRestoreMatches(state.Previous.Binding, intent) {
		return state.Previous, nil
	}
	var selected *nativeGoodRelease
	for i := range state.Good {
		good := &state.Good[i]
		if !nativeRestoreMatches(good.Binding, intent) {
			continue
		}
		if selected != nil && selected.Binding.ProfileDigest != good.Binding.ProfileDigest {
			return nil, fmt.Errorf("%w: rollback target identifies multiple retained resource profiles", delivery.ErrInvalid)
		}
		selected = good
	}
	if selected == nil {
		return nil, fmt.Errorf("%w: rollback target is not a retained good release/configuration pair", delivery.ErrInvalid)
	}
	return selected, nil
}

func (s *Service) getOperation(ctx context.Context, key string) (*operationValue, error) {
	if s == nil || s.config.Conn == nil {
		return nil, errors.New("delivery operation leader read requires NATS connection")
	}
	js, err := s.config.Conn.JetStream()
	if err != nil {
		return nil, err
	}
	subject := "$KV." + OperationBucket + "." + key
	msg, err := js.GetLastMsg("KV_"+OperationBucket, subject, nats.Context(ctx))
	if errors.Is(err, nats.ErrMsgNotFound) {
		return nil, jetstream.ErrKeyNotFound
	}
	if err != nil {
		return nil, err
	}
	return operationValueFromMsg(subject, msg)
}

func operationValueFromMsg(subject string, msg *nats.RawStreamMsg) (*operationValue, error) {
	if msg == nil || msg.Subject != subject || msg.Sequence == 0 {
		return nil, errors.New("invalid delivery operation state")
	}
	if operation := msg.Header.Get("KV-Operation"); operation != "" {
		if operation == "DEL" || operation == "PURGE" {
			return nil, jetstream.ErrKeyNotFound
		}
		return nil, errors.New("invalid delivery operation marker")
	}
	if marker := msg.Header.Get(jetstream.MarkerReasonHeader); marker != "" {
		if marker == "MaxAge" || marker == "Purge" || marker == "Remove" {
			return nil, jetstream.ErrKeyNotFound
		}
		return nil, errors.New("invalid delivery operation marker")
	}
	if len(msg.Data) == 0 {
		return nil, errors.New("invalid delivery operation body")
	}
	return &operationValue{value: msg.Data, revision: msg.Sequence}, nil
}

func (s *Service) status(ctx context.Context, operationID, expectedFingerprint string) (Receipt, error) {
	if s == nil || !entityid.Valid(operationID) {
		return Receipt{}, ErrInvalid
	}
	e, err := s.getOperation(ctx, operationKey(operationID))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Receipt{}, ErrPending
	}
	if err != nil {
		return Receipt{}, err
	}
	var op operation
	if err := json.Unmarshal(e.Value(), &op); err != nil {
		return Receipt{}, fmt.Errorf("decode delivery status: %w", err)
	}
	if op.Intent.OperationID != operationID {
		return Receipt{}, ErrConflict
	}
	fingerprint, err := op.Intent.Fingerprint()
	if err != nil || fingerprint != op.Fingerprint {
		return Receipt{}, fmt.Errorf("%w: invalid durable operation fingerprint", ErrInvalid)
	}
	if expectedFingerprint != "" && fingerprint != expectedFingerprint {
		return Receipt{}, ErrConflict
	}
	if op.Receipt == nil {
		return Receipt{}, ErrPending
	}
	if op.Receipt.OperationID != operationID || op.Receipt.Fingerprint != fingerprint || op.Receipt.ArtifactDigest != op.Intent.ArtifactDigest || op.Receipt.ManifestDigest != op.Intent.ManifestDigest {
		return Receipt{}, fmt.Errorf("%w: invalid durable delivery receipt", ErrInvalid)
	}
	return *op.Receipt, nil
}

func (s *Service) StatusFor(ctx context.Context, intent Intent) (Receipt, error) {
	fingerprint, err := intent.Fingerprint()
	if err != nil {
		return Receipt{}, err
	}
	return s.status(ctx, intent.OperationID, fingerprint)
}

func (s *Service) RefuseIntent(ctx context.Context, intent Intent, actor string, authorityEpoch uint64, reason string) error {
	if s == nil || s.operations == nil || s.config.Authorize == nil || s.config.Fencer == nil {
		return ErrInvalid
	}
	if actor == "" || reason == "" || len(reason) > 1024 || intent.Cell != s.config.Cell {
		return ErrInvalid
	}
	if err := intent.Validate(); err != nil {
		return err
	}
	if err := s.config.Authorize(ctx, actor, intent); err != nil {
		return err
	}
	if err := s.config.Fencer.Guard(ctx, authorityEpoch); err != nil {
		return err
	}
	wire, err := json.Marshal(intent)
	if err != nil {
		return err
	}
	terminal, err := s.recordIntentReceipt(ctx, wire, intent, actor, "rejected", reason)
	if err != nil {
		return err
	}
	if !terminal {
		return ErrConflict
	}
	entry, err := s.getOperation(ctx, operationKey(intent.OperationID))
	if err != nil {
		return err
	}
	var stored operation
	if err := json.Unmarshal(entry.Value(), &stored); err != nil {
		return err
	}
	fingerprint, err := intent.Fingerprint()
	if err != nil {
		return err
	}
	if stored.Fingerprint != fingerprint || stored.Actor != actor || stored.Receipt == nil || stored.Receipt.Status != "rejected" {
		return ErrConflict
	}
	return nil
}

func (c *Controller) ListDesired(ctx context.Context, role string) ([]Desired, error) {
	if c == nil || c.controlLog == nil || c.mutations == nil {
		return nil, errors.New("ordered host state reader is unavailable")
	}
	if role != "" {
		if err := validateToken(role, "role"); err != nil {
			return nil, err
		}
	}
	prefix := protocol.Control(c.cell, "host", "desired", c.cell) + "."
	filter := prefix + ">"
	if role != "" {
		filter = prefix + "*." + role
	}
	info, err := c.controlLogSubjects(ctx, filter)
	if err != nil {
		return nil, err
	}
	var result []Desired
	for subject := range info.State.Subjects {
		suffix, ok := strings.CutPrefix(subject, prefix)
		if !ok {
			return nil, errors.New("desired log subject has unexpected prefix")
		}
		node, roleName, ok := strings.Cut(suffix, ".")
		if !ok || validateToken(node, "node") != nil || validateToken(roleName, "role") != nil || strings.Contains(roleName, ".") {
			return nil, errors.New("desired log subject is malformed")
		}
		if role != "" && roleName != role {
			continue
		}
		d, revision, exists, err := c.readDesired(ctx, node, roleName)
		if err != nil {
			return nil, err
		}
		if !exists || revision == 0 {
			return nil, errors.New("desired log index is inconsistent")
		}
		result = append(result, d)
	}
	slices.SortFunc(result, func(a, b Desired) int {
		if a.Node < b.Node {
			return -1
		}
		if a.Node > b.Node {
			return 1
		}
		return strings.Compare(a.Role, b.Role)
	})
	return result, nil
}

func (c *Controller) readDesired(ctx context.Context, node, role string) (Desired, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Desired{}, 0, false, err
	}
	if err := validateToken(role, "role"); err != nil {
		return Desired{}, 0, false, err
	}
	key := desiredSubjectKey(c.cell, node, role)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationDesired, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Desired{}, 0, false, nil
	}
	if err != nil {
		return Desired{}, 0, false, err
	}
	if entry.Kind != authority.MutationDesired || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Desired{}, 0, false, errors.New("desired log entry is malformed")
	}
	var d Desired
	if err := decodeStrict(entry.Payload, &d); err != nil {
		return Desired{}, 0, false, err
	}
	if d.Cell != c.cell || d.Node != node || d.Role != role || d.AuthorityEpoch != entry.Epoch {
		return Desired{}, 0, false, errors.New("desired log identity or epoch mismatch")
	}
	return d, entry.Sequence, true, nil
}

func (c *Controller) controlLogSubjects(ctx context.Context, filter string) (*jetstream.StreamInfo, error) {
	if err := c.lockControlLog(ctx); err != nil {
		return nil, err
	}
	defer func() { <-c.controlLogInfoGate }()
	return c.controlLog.Info(ctx, jetstream.WithSubjectFilter(filter))
}

func OpenReader(ctx context.Context, js jetstream.JetStream, scope string) (*Reader, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	if !natsToken.MatchString(scope) {
		return nil, errors.New("authority scope must be a canonical ULID")
	}
	stream, err := js.Stream(ctx, ControlStreamName)
	if err != nil {
		return nil, err
	}
	info, err := stream.Info(ctx)
	if err != nil {
		return nil, err
	}
	if err := verifyControlStreamConfig(info.Config, info.Config.Replicas); err != nil {
		return nil, err
	}
	return &Reader{stream: stream, scope: scope}, nil
}

func (r *Reader) ReadHostMutation(ctx context.Context, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	if r == nil || r.stream == nil {
		return LogEntry{}, ErrNotFound
	}
	if err := validateMutationKey(kind, subjectKey); err != nil {
		return LogEntry{}, err
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	return readMutation(ctx, r.stream, r.scope, kind, subjectKey)
}

func readMutation(ctx context.Context, stream jetstream.Stream, scope string, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	subject := mutationSubject(scope, kind, subjectKey)
	entry, err := stream.GetLastMsgForSubject(ctx, subject)
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return LogEntry{}, ErrNotFound
	}
	if err != nil {
		return LogEntry{}, err
	}
	record, err := decodeControlRecord(entry.Data)
	if err != nil || record.Scope != scope || record.Kind != kind || record.SubjectKey != subjectKey || record.Epoch == 0 {
		return LogEntry{}, errors.New("host control log entry is invalid")
	}
	return LogEntry{
		Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID,
		Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: bytes.Clone(record.Payload),
	}, nil
}

func (c *Controller) ListHosts(ctx context.Context) ([]HostStatus, error) {
	if c.controlLog == nil {
		return nil, errors.New("ordered control log is required for host discovery")
	}
	prefix := protocol.Control(c.cell, "host", "registration", c.cell) + "."
	info, err := c.controlLogSubjects(ctx, prefix+"*")
	if err != nil {
		return nil, err
	}
	var hosts []HostStatus
	for subject := range info.State.Subjects {
		node, ok := strings.CutPrefix(subject, prefix)
		if !ok || validateToken(node, "node") != nil {
			return nil, errors.New("host registration subject is invalid")
		}
		r, registrationRevision, exists, err := c.readRegistration(ctx, node)
		if err != nil {
			return nil, err
		} else if !exists {
			continue
		}
		retirement, retirementRevision, err := c.readRetirement(ctx, node)
		if err != nil {
			return nil, err
		}
		status := HostStatus{Registration: r, Retired: retirement.Retired, Verified: !c.readOnly}
		s, _, exists, err := c.sessionSnapshot(ctx, sessionKey(c.cell, r.Node))
		if err != nil {
			return nil, err
		}
		if exists && s.RegistrationGeneration == r.Generation && time.Now().Before(s.ExpiresAt) {
			status.SessionExpiresAt = s.ExpiresAt
			for _, role := range r.Roles {
				report, _, ok, err := c.reportSnapshot(ctx, reportKey(c.cell, r.Node, role))
				if err != nil {
					return nil, err
				}
				if !ok || report.Cell != c.cell || report.Node != r.Node || report.Environment != r.Environment || report.Role != role ||
					report.SessionID != s.SessionID || report.Epoch != s.Epoch || time.Since(report.ObservedAt) >= ReportMaxAge || report.ObservedAt.After(time.Now().Add(maxClockSkew)) {
					continue
				}
				desired, desiredRevision, ok, err := c.readDesired(ctx, r.Node, role)
				if err != nil {
					return nil, err
				}
				if !ok || report.Generation != desired.Generation || report.Digest != desired.Digest || desired.Withdrawn && report.State == "running" ||
					validateManagedReportForDesired(report, desired) != nil {
					continue
				}
				confirmed, confirmedRevision, ok, err := c.readDesired(ctx, r.Node, role)
				if err != nil || !ok || confirmedRevision != desiredRevision || !sameJSON(confirmed, desired) {
					return nil, errors.New("desired changed during host status read")
				}
				check, _, ok, err := c.reportSnapshot(ctx, reportKey(c.cell, r.Node, role))
				if err != nil || !ok || check.ObservedAt.Before(report.ObservedAt) || !sameReportMeaning(check, report) ||
					check.SessionID != s.SessionID || check.Epoch != s.Epoch || check.Generation != desired.Generation || check.Digest != desired.Digest ||
					validateManagedReportForDesired(check, desired) != nil ||
					time.Since(check.ObservedAt) >= ReportMaxAge || check.ObservedAt.After(time.Now().Add(maxClockSkew)) || desired.Withdrawn && check.State == "running" {
					return nil, errors.New("report changed during host status read")
				}
				status.Reports = append(status.Reports, check)
			}
			check, _, ok, err := c.sessionSnapshot(ctx, sessionKey(c.cell, r.Node))
			if err != nil || !ok || check.RegistrationGeneration != r.Generation || check.SessionID != s.SessionID || check.Epoch != s.Epoch || !time.Now().Before(check.ExpiresAt) {
				return nil, errors.New("session changed during host status read")
			}
			status.SessionExpiresAt = check.ExpiresAt
		}
		confirmed, confirmedRevision, ok, err := c.readRegistration(ctx, node)
		if err != nil || !ok || confirmedRevision != registrationRevision || !sameJSON(confirmed, r) {
			return nil, errors.New("registration changed during host status read")
		}
		if _, revision, err := c.readRetirement(ctx, node); err != nil || revision != retirementRevision {
			return nil, errors.New("retirement changed during host status read")
		}
		hosts = append(hosts, status)
	}
	slices.SortFunc(hosts, func(a, b HostStatus) int { return strings.Compare(a.Registration.Node, b.Registration.Node) })
	return hosts, nil
}

func committedNativeBinding(state nativeReleaseHistory, desired host.Desired) *nativeReleaseBinding {
	for _, b := range nativeBindings(&state) {
		if desired.Generation != b.Intent.Generation && workload.ReleaseOf(desired.Generation) != b.Intent.Generation {
			continue
		}
		if desired.Cell == b.Intent.Cell && desired.Environment == b.Intent.Environment && desired.Digest == b.Artifact.Digest &&
			delivery.ConfigDigestOf(desired.Args, desired.Env, desired.Secrets) == b.Intent.ConfigDigest {
			return b
		}
	}
	return nil
}

func (h *nativeHistory) resources(ctx context.Context, desired []host.Desired, profiles map[string]placement.Resources) (map[string]placement.Resources, error) {
	profiles = maps.Clone(profiles)
	for _, role := range serviceReleaseRoles {
		var latest *host.Desired
		for i := range desired {
			d := &desired[i]
			if d.Role == role && !d.Withdrawn && (latest == nil || d.Generation > latest.Generation) {
				latest = d
			}
		}
		if latest == nil {
			continue
		}
		state, _, err := h.load(ctx, role)
		if err != nil {
			return nil, err
		}
		b := committedNativeBinding(state, *latest)
		if b == nil || state.Rejected == b.Fingerprint || latest.Generation != b.Intent.Generation && workload.ReleaseOf(latest.Generation) != b.Intent.Generation ||
			latest.Digest != b.Artifact.Digest || delivery.ConfigDigestOf(latest.Args, latest.Env, latest.Secrets) != b.Intent.ConfigDigest {
			return nil, errors.New("native reconciliation awaits the selected release profile")
		}
		if err := h.verifyProfile(role, b.Profile, b.Provenance); err != nil {
			return nil, err
		}
		profiles[role] = b.Profile.Resources
	}
	return profiles, nil
}

func (p *regionalDeliveryPlanner) Plan(ctx context.Context, intent delivery.Intent) ([]host.Desired, error) {
	var shape delivery.PlanShape
	return p.plan(ctx, intent, func(workload.Observation) (delivery.PlanShape, error) {
		return delivery.PlanShape{Generation: intent.Generation, Replicas: intent.DesiredReplicas}, nil
	}, &shape)
}

func (p *regionalDeliveryPlanner) plan(ctx context.Context, intent delivery.Intent,
	shapeOf func(workload.Observation) (delivery.PlanShape, error), shape *delivery.PlanShape,
) ([]host.Desired, error) {
	profiles := p.profiles()
	profile, ok := profiles[intent.Role]
	if !ok {
		return nil, fmt.Errorf("no workload profile for role %q", intent.Role)
	}
	if slices.Contains(serviceReleaseRoles, intent.Role) {
		if p.nativeHistory == nil {
			return nil, errors.New("native signed profile history is unavailable")
		}
		var err error
		profile, err = p.nativeHistory.profile(ctx, intent)
		if err != nil {
			return nil, err
		}
		profiles[intent.Role] = profile
	}
	if delivery.ConfigDigestOf(profile.Args, profile.Env, profile.Secrets) != intent.ConfigDigest {
		return nil, errors.New("intent configuration digest differs from controller workload profile")
	}
	statuses, err := p.hosts.ListHosts(ctx)
	if err != nil {
		return nil, err
	}
	allocations, err := p.hosts.ListDesired(ctx, "")
	if err != nil {
		return nil, err
	}
	if p.nativeHistory == nil {
		return nil, errors.New("native signed profile history is unavailable")
	}
	// The target uses its prepared profile; colocated roles use their committed reservations.
	otherAllocations := slices.DeleteFunc(slices.Clone(allocations), func(d host.Desired) bool { return d.Role == intent.Role })
	resources, err := p.nativeHistory.resources(ctx, otherAllocations, profileResources(profiles))
	if err != nil {
		return nil, err
	}
	observation, err := workload.Observe(workload.Snapshot{
		Cell: intent.Cell, Environment: intent.Environment, Role: intent.Role,
		Hosts: statuses, Desired: allocations, Profiles: resources, Now: time.Now(),
	})
	if err != nil {
		return nil, err
	}
	if *shape, err = shapeOf(observation); err != nil {
		return nil, err
	}
	candidates, previous := observation.Candidates, releaseFailures(observation, intent.ArtifactDigest, intent.ConfigDigest)
	if intent.Role == terrabase.Role {
		if candidates, previous, err = terraBasePlacement(profile, shape.Replicas, candidates, previous, p.address); err != nil {
			return nil, err
		}
	}
	maxPerFailureDomain := releasePlacementDomainCap(intent.Role)
	assignments, err := placement.PlanWorkload(placement.WorkloadRequest{
		Cell: intent.Cell, Role: intent.Role, Replicas: shape.Replicas,
		Request: profile.Resources, Hosts: candidates, Previous: previous, MaxPerFailureDomain: maxPerFailureDomain,
	})
	if err != nil {
		return nil, err
	}
	result := make([]host.Desired, 0, len(assignments))
	for _, assignment := range assignments {
		status, exists := observation.Statuses[assignment.Node]
		if !exists {
			return nil, errors.New("placement selected an unknown host")
		}
		desired := host.Desired{
			Cell: intent.Cell, Node: assignment.Node, Environment: status.Registration.Environment,
			Role: intent.Role, Generation: shape.Generation, AuthorityEpoch: intent.AuthorityEpoch,
			Withdrawn: assignment.Withdrawn,
		}
		if !assignment.Withdrawn {
			desired.Digest = intent.ArtifactDigest
			desired.Args = slices.Clone(profile.Args)
			desired.Env = maps.Clone(profile.Env)
			desired.Secrets = maps.Clone(profile.Secrets)
		}
		result = append(result, desired)
	}
	slices.SortFunc(result, func(a, b host.Desired) int { return strings.Compare(a.Node, b.Node) })
	return result, nil
}

func (t *hostTelemetry) setResources(resources map[string]placement.Resources) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.setRequests(loadRequests(resources))
}

// setRequests is called with mu held, including throughout usage recording.
func (t *hostTelemetry) setRequests(requests map[string]hostload.Request) {
	if maps.Equal(t.requests, requests) {
		return
	}
	t.requests = requests
	t.load.Reset()
	t.load.SetRequests(requests)
}

func (t *hostTelemetry) recordCommitted(ctx context.Context, history *nativeHistory, usage *runtimeObservability,
	origin hostload.Origin, report hostload.Report,
) error {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	desired, err := history.hosts.ListDesired(ctx, "")
	if err != nil {
		return err
	}
	resources, err := history.resources(ctx, desired, profileResources(history.services.profiles()))
	if err != nil {
		return err
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	if !t.current() {
		return authority.ErrFenced
	}
	t.setRequests(loadRequests(resources))
	return usage.recordHostLoad(t.load.Record, origin, report, t.requests)
}

func fenceKV(t *testing.T) jetstream.KeyValue {
	t.Helper()
	kv, _, _ := fenceBroker(t)
	return kv
}

func fenceBroker(t *testing.T) (jetstream.KeyValue, *nats.Conn, jetstream.JetStream) {
	t.Helper()
	srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true, StoreDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	srv.Start()
	t.Cleanup(srv.Shutdown)
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("NATS did not start")
	}
	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	kv, err := js.CreateKeyValue(t.Context(), jetstream.KeyValueConfig{Bucket: "TS_RELEASE_CHANNEL"})
	if err != nil {
		t.Fatal(err)
	}
	return kv, conn, js
}

// fenceLB is a load balancer whose backends report healthy unless listed in
// down. It fails the test when a set has no backend in rotation.
type fenceLB struct {
	t    *testing.T
	mu   sync.Mutex
	sets map[string][]lb.Backend
	down map[string]bool
	log  []string
	ids  []string // the load balancer of each update
}

func (f *fenceLB) ListBackends(_ context.Context, _, set string) ([]lb.Backend, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return slices.Clone(f.sets[set]), nil
}

func (f *fenceLB) UnhealthyBackends(_ context.Context, _, set string) (map[string]bool, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	unhealthy := map[string]bool{}
	for _, backend := range f.sets[set] {
		if f.down[backend.Name()] {
			unhealthy[backend.Name()] = true
		}
	}
	return unhealthy, nil
}

func (f *fenceLB) UpdateBackend(_ context.Context, id, set string, backend lb.Backend) (string, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.ids = append(f.ids, id)
	if !backend.Serving() {
		// Taking a backend out must leave another node's healthy one.
		alternative := false
		for _, other := range f.sets[set] {
			alternative = alternative || other.IP != backend.IP && other.Serving() && !f.down[other.Name()]
		}
		if !alternative {
			f.t.Errorf("took %s out of %s without a healthy backend on another node", backend.Name(), set)
		}
	}
	serving, state := 0, "active"
	for i, current := range f.sets[set] {
		if current.Name() == backend.Name() {
			// The fence drains, then sets the drained backend offline.
			switch {
			case backend.Serving():
			case current.Drain:
				state = "offline"
			default:
				state = "drain"
			}
			f.sets[set][i] = backend
		}
		if f.sets[set][i].Serving() {
			serving++
		}
	}
	f.log = append(f.log, set+" "+backend.Name()+" "+state)
	if serving == 0 {
		f.t.Errorf("set %s has no backend in rotation after %s", set, f.log[len(f.log)-1])
	}
	return "wr", nil
}

func (f *fenceLB) WaitWorkRequest(context.Context, string) error { return nil }
func (f *fenceLB) GetLoadBalancer(context.Context, string) (lb.LoadBalancer, error) {
	return lb.LoadBalancer{}, nil
}
func (f *fenceLB) CreateBackend(_ context.Context, _, set string, backend lb.Backend) (string, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.sets[set] = append(f.sets[set], backend)
	f.log = append(f.log, set+" "+backend.Name()+" created")
	return "wr", nil
}

func (c *fenceCell) ListDesired(context.Context, string) ([]host.Desired, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	var desired []host.Desired
	for _, node := range c.nodes {
		desired = append(desired, host.Desired{Node: node, Role: c.role, Generation: c.release << 24})
	}
	return desired, nil
}

func (l *fenceLease) Current() authority.Snapshot {
	l.mu.Lock()
	defer l.mu.Unlock()
	return authority.Snapshot{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Ready: true, Leader: !l.lost, Epoch: 3, Revision: 1, ExpiresAt: time.Now().Add(time.Hour)}
}

func (l *fenceLease) Guard(_ context.Context, epoch uint64) error {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.guards++
	if l.lose > 0 && l.guards >= l.lose {
		l.lost = true
	}
	if l.lost || epoch != 3 {
		return authority.ErrFenced
	}
	return nil
}

func newFenceTest(t *testing.T) (*releaseFence, *fenceCell, *fenceLB, jetstream.KeyValue, delivery.Intent) {
	t.Helper()
	kv := fenceKV(t)
	return newFenceTestWithStore(t, kv)
}

func newFenceTestWithStore(t *testing.T, kv jetstream.KeyValue) (*releaseFence, *fenceCell, *fenceLB, jetstream.KeyValue, delivery.Intent) {
	t.Helper()
	balancer := &fenceLB{t: t, down: map[string]bool{}, sets: map[string][]lb.Backend{}}
	for _, node := range []string{"ctl-1", "ctl-2", "ctl-3"} {
		balancer.sets["terrabase"] = append(balancer.sets["terrabase"], lb.Backend{IP: fenceAddresses[node], Port: 9465})
		// ctl-1's ts-auth backend is out of rotation already.
		balancer.sets["ts-auth"] = append(balancer.sets["ts-auth"],
			lb.Backend{IP: fenceAddresses[node], Port: 8080}.Fenced(node == "ctl-1", node == "ctl-1"))
	}
	spec := &cellspec.ReleaseFence{LoadBalancerID: "ocid1.loadbalancer.oc1..x",
		BackendSets: []cellspec.FencedSet{{Name: "terrabase", Port: 9465, MinServing: 1}, {Name: "ts-auth", Port: 8080, MinServing: 1}}}
	cell := &fenceCell{t: t, gate: releaseGate(kv), lb: balancer, nodes: []string{"ctl-1", "ctl-2", "ctl-3"}, release: 7, role: "ts-auth",
		broken: map[string]bool{}}
	fence := &releaseFence{kv: kv, hosts: cell, fencer: &fenceLease{},
		spec: func() (*cellspec.ReleaseFence, map[string]string) { return spec, fenceAddresses },
		open: func(context.Context) (lb.API, error) { return balancer, nil },
		sleep: func(ctx context.Context, _ time.Duration) error {
			time.Sleep(time.Millisecond)
			return ctx.Err()
		}}
	return fence, cell, balancer, kv, delivery.Intent{Role: "ts-auth", Generation: 7}
}

func (l *fenceLease) ReadNetBirdState(context.Context) (authority.LogEntry, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.netbird.Sequence == 0 {
		return authority.LogEntry{}, authority.ErrNotFound
	}
	entry := l.netbird
	entry.Payload = slices.Clone(entry.Payload)
	return entry, nil
}

func (l *fenceLease) CommitNetBirdState(ctx context.Context, epoch uint64, operation string, expected uint64, wire []byte) (uint64, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if err := ctx.Err(); err != nil {
		return 0, err
	}
	if l.lost || epoch != 3 {
		return 0, authority.ErrFenced
	}
	if l.netbird.Sequence != expected {
		return 0, authority.ErrConflict
	}
	l.netbird = authority.LogEntry{Epoch: epoch, Sequence: expected + 1, OperationID: operation, Payload: slices.Clone(wire)}
	return l.netbird.Sequence, nil
}

func saveNetBirdTestAdmission(ctx context.Context, n *netbirdRollout, epoch uint64, record network.Record) error {
	state, err := n.state(ctx)
	if err != nil {
		return err
	}
	return n.saveRecordAt(ctx, epoch, &state, record)
}

func readNetBirdState(ctx context.Context, reader netbirdStateReader) (netbirdState, error) {
	entry, err := reader.ReadNetBirdState(ctx)
	if errors.Is(err, authority.ErrNotFound) {
		return netbirdState{}, nil
	}
	if err != nil {
		return netbirdState{}, err
	}
	return decodeNetBirdState(entry)
}

func decodeNetBirdState(entry authority.LogEntry) (netbirdState, error) {
	var state netbirdState
	if entry.Sequence == 0 || entry.Epoch == 0 {
		return state, errors.New("invalid NetBird journal revision")
	}
	if err := json.Unmarshal(entry.Payload, &state, json.RejectUnknownMembers(true)); err != nil {
		return state, err
	}
	if (state.Record.ID != "" || state.Record.Phase != "" || state.Record.Node != "") && !entityid.Valid(state.Record.ID) {
		return state, errors.New("invalid NetBird journal identity")
	}
	state.Revision = entry.Sequence
	return state, nil
}

func (n *netbirdRollout) state(ctx context.Context) (netbirdState, error) {
	reader, ok := n.fence.fencer.(netbirdStateReader)
	if !ok {
		return netbirdState{}, errors.New("NetBird requires an authority journal reader")
	}
	return readNetBirdState(ctx, reader)
}

func (n *netbirdRollout) commitStateAt(ctx context.Context, epoch uint64, state *netbirdState, next netbirdState) error {
	store, ok := n.fence.fencer.(netbirdStateStore)
	if !ok {
		return errors.New("NetBird requires an authority journal writer")
	}
	if (next.Record.ID != "" || next.Record.Phase != "" || next.Record.Node != "") && !entityid.Valid(next.Record.ID) {
		return errors.New("invalid NetBird journal identity")
	}
	original, err := json.Marshal(*state, json.Deterministic(true))
	if err != nil {
		return err
	}
	wire, err := json.Marshal(next, json.Deterministic(true))
	if err != nil {
		return err
	}
	expected, operation := state.Revision, entityid.New()
	for attempt := range 3 {
		revision, err := store.CommitNetBirdState(ctx, epoch, operation, expected, wire)
		if err == nil {
			next.Revision = revision
			*state = next
			return nil
		}
		if !errors.Is(err, authority.ErrConflict) || attempt == 2 {
			return err
		}
		current, err := readNetBirdState(ctx, store)
		if err != nil {
			return err
		}
		currentWire, err := json.Marshal(current, json.Deterministic(true))
		if err != nil {
			return err
		}
		// Issuance changes only the revision; a changed intent invalidates
		// the original tick's health, drain and return decisions.
		if !bytes.Equal(original, currentWire) {
			return authority.ErrConflict
		}
		expected = current.Revision
	}
	return authority.ErrConflict
}

func (n *netbirdRollout) loadIntent(ctx context.Context, key string, value any) error {
	state, err := n.state(ctx)
	if err != nil {
		return err
	}
	if state.Revision == 0 {
		return os.ErrNotExist
	}
	var intent any = state.Record
	if key != netbirdRecordKey {
		if key != "netbird.command."+state.Record.Node {
			return os.ErrNotExist
		}
		command, found, err := state.commandFor(state.Record.Node)
		if err != nil {
			return err
		}
		if !found {
			return os.ErrNotExist
		}
		intent = command
	}
	wire, err := json.Marshal(intent)
	if err != nil {
		return err
	}
	return json.Unmarshal(wire, value, json.RejectUnknownMembers(true))
}

func (n *netbirdRollout) load(ctx context.Context, key string, value any) error {
	if key == netbirdRecordKey || strings.HasPrefix(key, "netbird.command.") {
		return n.loadIntent(ctx, key, value)
	}
	return n.fence.loadJSON(ctx, key, value)
}

func (n *netbirdRollout) saveAt(ctx context.Context, epoch uint64, key string, value any) error {
	if !strings.HasPrefix(key, "netbird.status.") {
		return errors.New("NetBird intent requires a conditional authority commit")
	}
	wire, err := json.Marshal(value)
	if err != nil {
		return err
	}
	if err := n.fence.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = n.fence.kv.Put(ctx, key, wire)
	return err
}

func (n *netbirdRollout) saveRecordAt(ctx context.Context, epoch uint64, state *netbirdState, record network.Record) error {
	if record.Phase == "drain" && len(record.Fence) == 0 {
		spec, addresses := n.addresses()
		if spec == nil || addresses[record.Node] == "" {
			return errors.New("NetBird admission requires a release fence and verified OCI address")
		}
		if err := netbirdOCIAddress(addresses[record.Node]); err != nil {
			return err
		}
		wire, err := json.Marshal(spec)
		if err != nil {
			return err
		}
		record.Fence, record.OCIAddress = wire, addresses[record.Node]
	}
	next := *state
	if next.Record.ID != record.ID || next.Record.Node != record.Node {
		next.Command = network.Command{}
	}
	next.Record = record
	if !netbirdCommandAllowed(record, next.Command.Action) {
		next.Command = network.Command{}
	}
	return n.commitStateAt(ctx, epoch, state, next)
}

func netbirdAdmittedFence(record network.Record) (*cellspec.ReleaseFence, error) {
	var admitted *cellspec.ReleaseFence
	if err := json.Unmarshal(record.Fence, &admitted, json.RejectUnknownMembers(true)); err != nil {
		return nil, fmt.Errorf("decode admitted NetBird fence: %w", err)
	}
	if admitted == nil {
		return nil, errors.New("NetBird admission has no release fence")
	}
	if err := netbirdOCIAddress(record.OCIAddress); err != nil {
		return nil, err
	}
	return admitted, nil
}

func (n *netbirdRollout) preflightAddresses(ctx context.Context, node string) (*cellspec.ReleaseFence, map[string]string, error) {
	spec, addresses := n.addresses()
	state, err := n.state(ctx)
	if err != nil {
		return nil, nil, err
	}
	record := state.Record
	if record.ID != "" && record.Node == node && record.Phase != "done" && !record.RecoveryComplete && len(record.Fence) > 0 {
		spec, err = netbirdAdmittedFence(record)
		if err != nil {
			return nil, nil, err
		}
		// Only the admitted node keeps its saved address. Peers still come
		// from the current inventory and pass live health/quorum checks.
		addresses[node] = record.OCIAddress
	}
	return spec, addresses, nil
}

func (n *netbirdRollout) refreshInventory(ctx context.Context) error {
	var record network.Record
	if err := n.load(ctx, netbirdRecordKey, &record); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	if record.ID == "" || record.Phase == "done" || record.Phase == "failed" && record.RecoveryComplete {
		return n.refreshManaged(ctx)
	}
	if record.OCIAddress != "" {
		if err := netbirdOCIAddress(record.OCIAddress); err != nil {
			return fmt.Errorf("persisted NetBird OCI recovery address is invalid: %w", err)
		}
		inventoryCtx, cancel := context.WithTimeout(ctx, 8*time.Second)
		err := n.refreshManaged(inventoryCtx)
		cancel()
		if err != nil && record.Phase == "drain" {
			return err
		}
		// Peer discovery cannot hold rollback/return of an already drained node.
		if n.managedAddresses == nil {
			n.managedAddresses = map[string]string{}
		}
		n.managedAddresses[record.Node] = record.OCIAddress
		return nil
	}
	return n.refreshRecoveryNode(ctx, record.Node)
}

func (n *netbirdRollout) refreshManaged(ctx context.Context) error {
	if time.Since(n.observed) < 30*time.Second {
		return nil
	}
	hosts, err := n.fence.hosts.ListHosts(ctx)
	if err != nil {
		return err
	}
	now := time.Now()
	candidates := make([]host.HostStatus, 0, len(hosts))
	for _, h := range hosts {
		if h.Registration.ManagedOCI != nil && now.Before(h.SessionExpiresAt) {
			candidates = append(candidates, h)
		}
	}
	addresses := map[string]string{}
	if len(candidates) != 0 && n.fleet != nil {
		instances, err := n.observeManaged(ctx, candidates)
		if err != nil {
			return err
		}
		for _, h := range candidates {
			if address, err := netbirdManagedAddress(h.Registration, instances); err == nil {
				addresses[h.Registration.Node] = address
			}
		}
	}
	n.managedAddresses, n.observed = addresses, now
	return nil
}

func (n *netbirdRollout) drainNode(ctx context.Context, epoch uint64, node string) error {
	// Bound the journal read too, before the admitted grace is known.
	readCtx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()
	var record network.Record
	if err := n.load(readCtx, netbirdRecordKey, &record); err != nil {
		return err
	}
	if record.Node != node || record.Deadline.IsZero() {
		return errors.New("NetBird drain requires this node's persisted phase deadline")
	}
	spec, addresses := n.addresses()
	address := addresses[node]
	if len(record.Fence) > 0 {
		admitted, err := netbirdAdmittedFence(record)
		if err != nil {
			return err
		}
		spec, address = admitted, record.OCIAddress
	}
	if spec == nil || address == "" {
		return errors.New("NetBird recovery has no admitted release fence or OCI address")
	}
	grace := durationOr(spec.DrainGraceSeconds, defaultFenceGrace)
	deadline := time.Now().Add(grace + 30*time.Second)
	ctx, cancelDrain := context.WithDeadline(ctx, deadline)
	defer cancelDrain()
	// Recovery must remain retryable after quorum repairs, even when its
	// previous acknowledgment deadline expired while waiting to re-drain.
	if record.Phase == "drain" && record.Deadline.Before(deadline) {
		var cancelPhase context.CancelFunc
		ctx, cancelPhase = context.WithDeadline(ctx, record.Deadline)
		defer cancelPhase()
	}
	if err := n.fence.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	api, err := n.fence.client(ctx)
	if err != nil {
		return err
	}
	return n.fence.fence(ctx, api, epoch, *spec, node, address, grace, netbirdHold)
}

func (f *releaseFence) loadJSON(ctx context.Context, key string, value any) error {
	entry, err := f.kv.Get(ctx, key)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return os.ErrNotExist
	}
	if err != nil {
		return err
	}
	return json.Unmarshal(entry.Value(), value, json.RejectUnknownMembers(true))
}

// keys lists the bucket's keys that match filter.
func (f *releaseFence) keys(ctx context.Context, filter string) ([]string, error) {
	lister, err := f.kv.ListKeysFiltered(ctx, filter)
	if errors.Is(err, jetstream.ErrNoKeysFound) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	defer lister.Stop()
	var keys []string
	for key := range lister.Keys() {
		keys = append(keys, key)
	}
	// The lister closes early, without an error, when ctx ends.
	return keys, ctx.Err()
}

func (f *releaseFence) fence(ctx context.Context, api lb.API, epoch uint64, spec cellspec.ReleaseFence, node,
	address string, grace time.Duration, holder string,
) error {
	if address == "" {
		// No host grant names the node: its backends are unknown, so it is
		// never restarted unfenced.
		return fmt.Errorf("no host grant gives the address of %s; its restart stays held", node)
	}
	unlock, err := f.lockNodeContext(ctx, node)
	if err != nil {
		return err
	}
	defer unlock()
	return f.fenceLocked(ctx, api, epoch, spec, node, address, grace, holder)
}

// fenceLocked is fence with node's lock held.
func (f *releaseFence) fenceLocked(ctx context.Context, api lb.API, epoch uint64, spec cellspec.ReleaseFence, node,
	address string, grace time.Duration, holder string,
) error {
	record, found, err := f.record(ctx, node)
	if err != nil {
		return err
	}
	added := !slices.Contains(record.holders(), holder)
	if added {
		record.Holders = append(slices.Clone(record.holders()), holder)
		if !found {
			record.Holders = []string{holder}
		}
		slices.Sort(record.Holders)
	}
	for _, set := range spec.BackendSets {
		observed, err := api.ListBackends(ctx, spec.LoadBalancerID, set.Name)
		if err != nil {
			return err
		}
		for _, backend := range observed {
			if backend.IP != address || backend.Port != set.Port || !backend.Serving() ||
				slices.ContainsFunc(record.Backends, func(recorded fencedBackend) bool {
					return recorded.LoadBalancerID == spec.LoadBalancerID && recorded.Set == set.Name &&
						recorded.IP == address && recorded.Port == set.Port
				}) {
				continue
			}
			weight, backup := backend.Shape()
			record.Backends = append(record.Backends, fencedBackend{LoadBalancerID: spec.LoadBalancerID, Set: set.Name,
				IP: address, Port: set.Port, Weight: weight, Backup: backup, Minimum: set.Min()})
			added = true
		}
	}
	if added || !found {
		if err := f.save(ctx, epoch, node, record); err != nil {
			return err
		}
	}
	return f.takeOutRecord(ctx, api, epoch, node, record, grace)
}

// takeOutRecord takes the recorded backends that are not offline yet out
// of rotation, each under the quorum guard, and records them offline.
func (f *releaseFence) takeOutRecord(ctx context.Context, api lb.API, epoch uint64, node string, record fenceRecord,
	grace time.Duration,
) error {
	if !slices.ContainsFunc(record.Backends, func(backend fencedBackend) bool { return !backend.Offline }) {
		return nil
	}
	for _, offline := range []bool{false, true} {
		for _, backend := range record.Backends {
			if backend.Offline {
				continue
			}
			if err := f.takeOut(ctx, api, epoch, backend, node, offline); err != nil {
				return err
			}
		}
		if !offline {
			// In-flight requests finish on the drained backends.
			if err := f.wait(ctx, epoch, grace); err != nil {
				return err
			}
		}
	}
	for i := range record.Backends {
		record.Backends[i].Offline = true
	}
	if err := f.save(ctx, epoch, node, record); err != nil {
		return err
	}
	slog.InfoContext(ctx, "release fence took a node out of rotation", observability.ComponentKey, "rollout", "node", node,
		"backends", len(record.Backends))
	return nil
}

func (f *releaseFence) record(ctx context.Context, node string) (fenceRecord, bool, error) {
	entry, err := f.kv.Get(ctx, fencedKey(node))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return fenceRecord{}, false, nil
	}
	if err != nil {
		return fenceRecord{}, false, err
	}
	var record fenceRecord
	if err := json.Unmarshal(entry.Value(), &record); err != nil {
		return fenceRecord{}, false, fmt.Errorf("decode the fence of %s: %w", node, err)
	}
	return record, true, nil
}

func (f *releaseFence) save(ctx context.Context, epoch uint64, node string, record fenceRecord) error {
	wire, err := json.Marshal(record)
	if err != nil {
		return err
	}
	if err := f.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = f.kv.Put(ctx, fencedKey(node), wire)
	return err
}

func (f *releaseFence) restore(ctx context.Context, api lb.API, epoch uint64, node, holder string, healthy bool) (bool, error) {
	unlock, err := f.lockNodeContext(ctx, node)
	if err != nil {
		return false, err
	}
	defer unlock()
	return f.restoreLocked(ctx, api, epoch, node, holder, healthy)
}

// restoreLocked is restore with node's lock held.
func (f *releaseFence) restoreLocked(ctx context.Context, api lb.API, epoch uint64, node, holder string, healthy bool,
) (bool, error) {
	record, found, err := f.record(ctx, node)
	if err != nil || !found {
		return false, err
	}
	if others := slices.DeleteFunc(slices.Clone(record.holders()), func(h string) bool { return h == holder }); len(others) > 0 {
		if len(others) == len(record.holders()) {
			return false, nil
		}
		record.Holders = others
		return false, f.save(ctx, epoch, node, record)
	}
	// Recorded as back in rotation before the load balancer changes, so a
	// restore cut short leaves a record the next fence drains again; the
	// holder stays on it until it is gone, so the holder finishes it.
	record.Holders = []string{holder}
	for i := range record.Backends {
		record.Backends[i].Offline = false
	}
	if err := f.save(ctx, epoch, node, record); err != nil {
		return false, err
	}
	for _, backend := range record.Backends {
		if err := f.update(ctx, api, epoch, backend, false, false); err != nil {
			return false, err
		}
	}
	for _, backend := range record.Backends {
		name := lb.Backend{IP: backend.IP, Port: backend.Port}.Name()
		for healthy {
			unhealthy, err := api.UnhealthyBackends(ctx, backend.LoadBalancerID, backend.Set)
			if err != nil {
				return false, err
			}
			if !unhealthy[name] {
				break
			}
			if err := f.wait(ctx, epoch, fencePoll); err != nil {
				return false, fmt.Errorf("%s backend %s did not pass its health check: %w", backend.Set, name, err)
			}
		}
	}
	if err := f.fencer.Guard(ctx, epoch); err != nil {
		return false, err
	}
	slog.InfoContext(ctx, "release fence returned a node to rotation", observability.ComponentKey, "rollout", "node", node)
	return len(record.Backends) > 0, f.kv.Delete(ctx, fencedKey(node))
}

func (f *releaseFence) reconcile(ctx context.Context) error {
	if f == nil {
		return nil
	}
	if spec, _ := f.spec(); spec != nil {
		return nil
	}
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()
	fenced, err := f.keys(ctx, fencedKey("*"))
	if err != nil {
		return err
	}
	marks, err := f.keys(ctx, "fence.>")
	if err != nil {
		return err
	}
	if len(fenced) == 0 && len(marks) == 0 {
		return nil
	}
	epoch, err := f.leading(ctx)
	if err != nil {
		return err
	}
	if len(fenced) > 0 {
		api, err := f.client(ctx)
		if err != nil {
			return err
		}
		for _, key := range fenced {
			if _, err := f.restore(ctx, api, epoch, strings.TrimPrefix(key, fencedKey("")), holdRelease, false); err != nil {
				return err
			}
		}
	}
	for _, key := range marks {
		if err := f.deleteGuarded(ctx, epoch, key); err != nil {
			return err
		}
	}
	return nil
}

func netbirdArtifactStore(t *testing.T, conn *nats.Conn) jetstream.ObjectStore {
	t.Helper()
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	store, err := js.CreateObjectStore(t.Context(), jetstream.ObjectStoreConfig{Bucket: delivery.ArtifactBucket})
	if err != nil {
		t.Fatal(err)
	}
	return store
}

func stageTestNetbirdArtifacts(t *testing.T, store jetstream.ObjectStore, pin client.Pin) {
	t.Helper()
	for architecture, digest := range map[string]string{"arm64": pin.Archives.Arm64.BinarySHA256, "amd64": pin.Archives.AMD64.BinarySHA256} {
		body := netbirdArtifactELF(architecture)
		if netbirdStageDigest(body) != digest {
			t.Fatal("artifact fixture pin does not match its ELF bytes")
		}
		if _, err := store.PutBytes(t.Context(), "sha256-"+digest, body); err != nil {
			t.Fatal(err)
		}
	}
}

func netbirdArtifactTest(t *testing.T, deniedDigest string) (*netbirdRollout, client.Pin, jetstream.JetStream) {
	t.Helper()
	pin := netbirdArtifactTestPin(t)
	deniedSubject := "$O." + delivery.ArtifactBucket + ".M." + base64.URLEncoding.EncodeToString([]byte("sha256-"+deniedDigest))
	broker, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true, StoreDir: t.TempDir(), Users: []*server.User{
		{Username: "admin", Password: "admin"},
		{Username: "admission", Password: "admission", Permissions: &server.Permissions{
			Publish:   &server.SubjectPermission{Allow: []string{">"}, Deny: []string{deniedSubject}},
			Subscribe: &server.SubjectPermission{Allow: []string{">"}},
		}},
	}})
	if err != nil {
		t.Fatal(err)
	}
	broker.Start()
	t.Cleanup(func() { broker.Shutdown(); broker.WaitForShutdown() })
	if !broker.ReadyForConnections(5 * time.Second) {
		t.Fatal("artifact NATS did not start")
	}
	connect := func(user string) *nats.Conn {
		t.Helper()
		conn, err := nats.Connect(broker.ClientURL(), nats.UserInfo(user, user), nats.ErrorHandler(func(*nats.Conn, *nats.Subscription, error) {}))
		if err != nil {
			t.Fatal(err)
		}
		t.Cleanup(conn.Close)
		return conn
	}
	conn := connect("admin")
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	kv, err := js.CreateKeyValue(t.Context(), jetstream.KeyValueConfig{Bucket: "TS_RELEASE_CHANNEL"})
	if err != nil {
		t.Fatal(err)
	}
	r := &netbirdRollout{cell: "gru", conn: conn, fence: &releaseFence{kv: kv, fencer: &fenceLease{}}, services: &specRegistry{}, artifacts: netbirdArtifactStore(t, conn)}
	if deniedDigest != "" {
		r.conn = connect("admission")
	}
	return r, pin, js
}

func (n *netbirdRollout) status(ctx context.Context, node string) (network.Status, error) {
	var status network.Status
	if err := n.load(ctx, "netbird.status."+node, &status); err != nil {
		return status, fmt.Errorf("NetBird worker on %s has not reported: %w", node, err)
	}
	if time.Since(status.ObservedAt) > 15*time.Second {
		return status, fmt.Errorf("NetBird worker on %s is stale", node)
	}
	return status, nil
}

func (n *netbirdRollout) addresses() (*cellspec.ReleaseFence, map[string]string) {
	spec, addresses := n.fence.spec()
	for node, address := range n.managedAddresses {
		if addresses[node] == "" {
			addresses[node] = address
		}
	}
	return spec, addresses
}

func (n *netbirdRollout) preflight(ctx context.Context, node string) error {
	if err := n.artifactsReady(ctx); err != nil {
		return err
	}
	spec, addresses, err := n.preflightAddresses(ctx, node)
	if err != nil {
		return err
	}
	if spec == nil || addresses[node] == "" || len(addresses) < 2 {
		return errors.New("NetBird upgrade requires a release fence and at least two granted nodes")
	}
	leader := n.services.controllerNode(n.cell, n.cfg.NATS.Instance)
	probe, err := n.status(ctx, leader)
	if err != nil {
		return err
	}
	if probe.Missing || probe.Version == "" || !probe.Connected {
		return errors.New("NetBird probing leader has no working mesh client; restore verified bootstrap enrollment over OCI before draining")
	}
	// Refuse a cell already being drained by another rollout. Quorum guards
	// in fence.fence still serialize every actual LB removal.
	keys, err := n.fence.keys(ctx, fencedKey("*"))
	if err != nil {
		return err
	}
	for _, key := range keys {
		record, found, err := n.fence.record(ctx, strings.TrimPrefix(key, fencedKey("")))
		if err != nil {
			return err
		}
		if found && slices.ContainsFunc(record.holders(), func(holder string) bool { return holder != netbirdHold }) {
			return fmt.Errorf("NetBird rollout waits for existing fence on %s", strings.TrimPrefix(key, fencedKey("")))
		}
	}
	if n.nodes != nil && n.nodes.cluster != nil {
		if err := n.nodes.cluster(ctx, node); err != nil {
			return err
		}
	}
	// Verify ordinary SSH on the OCI VCN address. We never change sshd,
	// networking, security lists, public IPs or this independent path.
	if err := n.recoverySSH(ctx, node, addresses[node]); err != nil {
		return fmt.Errorf("OCI SSH recovery path for %s is unavailable: %w", node, err)
	}
	selected, err := n.status(ctx, node)
	if err != nil {
		return err
	}
	bootstrapRemote := selected.Missing && selected.Version == "" && node != n.services.controllerNode(n.cell, n.cfg.NATS.Instance)
	for candidate := range addresses {
		status, err := n.status(ctx, candidate)
		if err != nil {
			return err
		}
		if status.Pending != "" || status.Error != "" {
			return fmt.Errorf("NetBird preflight %s has an unresolved worker operation", candidate)
		}
		// Several joining nodes may need their first authenticated install.
		// Only explicit executable absence can skip mesh health; a failed
		// observation of an installed daemon must still hold the rollout.
		if status.Missing && status.Version == "" {
			continue
		}
		// An unchanged installed leader can admit its first missing peer.
		// Confirmation still proves that peer's traffic over the mesh.
		if err := n.healthyMesh(ctx, candidate, status, time.Time{}, !bootstrapRemote); err != nil {
			return fmt.Errorf("NetBird preflight %s: %w", candidate, err)
		}
	}
	return nil
}

func (n *netbirdRollout) artifactsReady(ctx context.Context) error {
	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()
	if err := ctx.Err(); err != nil {
		return err
	}
	pin, err := n.target(ctx)
	if err != nil {
		return err
	}
	if pin == nil || n.artifacts == nil {
		return errors.New("NetBird artifacts are not configured")
	}
	if n.conn == nil {
		return errors.New("NetBird artifact admission requires the controller's NATS connection")
	}
	js, err := jetstream.New(n.conn)
	if err != nil {
		return err
	}
	legacy, err := n.conn.JetStream()
	if err != nil {
		return err
	}
	binaries := [2]struct{ architecture, digest string }{
		{"arm64", pin.Pin.Archives.Arm64.BinarySHA256},
		{"amd64", pin.Pin.Archives.AMD64.BinarySHA256},
	}
	var metadata [2]*nats.RawStreamMsg
	for i, binary := range binaries {
		name := "sha256-" + binary.digest
		subject := "$O." + delivery.ArtifactBucket + ".M." + base64.URLEncoding.EncodeToString([]byte(name))
		meta, err := legacy.GetLastMsg("OBJ_"+delivery.ArtifactBucket, subject, nats.Context(ctx))
		if err != nil {
			return fmt.Errorf("NetBird artifact %s is not staged; no node will be drained: %w", binary.digest, err)
		}
		var info jetstream.ObjectInfo
		if json.Unmarshal(meta.Data, &info) != nil || info.Name != name || info.Bucket != delivery.ArtifactBucket ||
			info.Deleted || info.Size < 64 || info.Size > client.MaxBinaryBytes {
			return fmt.Errorf("NetBird artifact %s is not staged; no node will be drained", binary.digest)
		}
		n.artifactMu.Lock()
		// Object-store writes replace metadata for changed chunks; direct
		// administrative chunk mutation must not bypass that contract.
		verified := bytes.Equal(n.verifiedMetadata[i], meta.Data)
		n.artifactMu.Unlock()
		if !verified {
			if err := verifyNetBirdArtifactContents(ctx, binary.digest, binary.architecture, func(dst io.Writer) error {
				return artifact.ReadVerifiedAuthoritative(ctx, js, &info, delivery.ArtifactBucket, name, binary.digest,
					int64(info.Size), client.MaxBinaryBytes, dst)
			}); err != nil {
				return fmt.Errorf("verify NetBird artifact %s (%s) before drain: %w", binary.digest, binary.architecture, err)
			}
			n.artifactMu.Lock()
			n.verifiedMetadata[i] = meta.Data
			n.artifactMu.Unlock()
		}
		metadata[i] = meta
	}
	// Fence collectors that selected these objects before the pin became active.
	for i, binary := range binaries {
		if err := artifact.Touch(ctx, legacy, delivery.ArtifactBucket, "sha256-"+binary.digest); err != nil {
			return fmt.Errorf("retain NetBird artifact %s before drain: %w", binary.digest, err)
		}
		meta, err := legacy.GetLastMsg("OBJ_"+delivery.ArtifactBucket, metadata[i].Subject, nats.Context(ctx))
		if err != nil {
			return err
		}
		// Touch keeps the bytes unchanged; replacement requires fresh verification.
		if !bytes.Equal(meta.Data, metadata[i].Data) {
			return fmt.Errorf("retain NetBird artifact %s before drain: %w", binary.digest, artifact.ErrChanged)
		}
	}
	return ctx.Err()
}
